import itertools

def check_n(n):
    N = n * (n - 1) // 2
    for s in range(3, N + 1):
        x = (3 - s) / 2
        a = [0] * n
        a[0] = x
        a[1] = 1 - x
        a[2] = 2 - x

        sums = {a[0]+a[1], a[0]+a[2], a[1]+a[2]}

        def solve(idx, current_sums):
            if idx == n:
                return True

            remaining_sums = set(range(1, N + 1)) - current_sums
            for s0 in list(remaining_sums):
                val = s0 - a[0]
                possible_sums = set()
                possible = True
                for i in range(idx):
                    s_val = a[i] + val
                    if s_val not in remaining_sums or (i != 0 and s_val == s0):
                        possible = False
                        break
                    if i != 0:
                        possible_sums.add(s_val)

                if possible:
                    if any(val == a[i] for i in range(idx)):
                        continue
                    a[idx] = val
                    if solve(idx + 1, current_sums | possible_sums | {s0}):
                        return True
            return False

        if solve(3, sums):
            return a
    return None

for n in range(3, 8):
    res = check_n(n)
    print(f"n={n}: {res}")
